# owner: platform
import unittest

from hourglass.rounding import round_spans
from hourglass.models import Span


class RoundingTests(unittest.TestCase):
    def test_label(self):
        self.assertEqual(
            round_spans([Span(540, 1035)], 15),
            ["09:00-17:15 (8h 15m)"]
        )

    def test_rounds_to_nearest(self):
        self.assertEqual(
            round_spans([Span(547, 1028)], 15),
            ["09:00-17:15 (8h 15m)"]
        )

    def test_halfway_rounds_up(self):
        self.assertEqual(round_spans([Span(545, 600)], 10), ["09:10-10:00 (0h 50m)"])

    def test_bad_steps(self):
        for step in (0, -5, 7, 45):
            with self.assertRaises(ValueError):
                round_spans([Span(540, 600)], step)
